generator client {
  provider = "prisma-client-js"
}

datasource db {
  provider = "postgresql"
}

enum UserRole {
  DEFAULT
  REFERRAL_PARTNER
  SELLER
  ADMIN
  ULTRA_ADMIN
  OWNER
}

enum Currency {
  RUB
}

enum OrderStatus {
  CREATED
  AWAITING_PAYMENT
  PAID
  SHIPPED
  DELIVERED
  CASHBACK_ACCRUED
  CANCELLED
}

enum CatalogCollectionType {
  CATEGORY
  PRODUCT
}

enum AdStatus {
  DRAFT
  PENDING_MODERATION
  PUBLISHED
  REJECTED
  ARCHIVED
}

model User {
  id             String    @id @default(uuid())
  email          String?
  nickname       String
  nicknameSuffix String    @unique @default(dbgenerated("gen_random_uuid()"))
  firstName      String?
  lastName       String?
  role           UserRole  @default(DEFAULT)
  createdAt      DateTime  @default(now())
  updatedAt      DateTime  @updatedAt
  deletedAt      DateTime?

  passwordHash String?
  oauthProvider String?
  oauthProviderId String?

  patronymic   String?
  phone        String?
  referralCode String?

  avatarId String?
  avatar   Image?  @relation("UserAvatar", fields: [avatarId], references: [id])

  @@unique([oauthProvider, oauthProviderId])
  @@index([phone])

  cartItems  CartItem[]
  orders     Order[]
  ads        Ad[]
  favourites Favourite[]

  invitedReferrals Referral[] @relation("Inviter")
  receivedReferral Referral?  @relation("Invited")
  balance          Balance?
}

model OtpCode {
  id        String   @id @default(uuid())
  login     String
  type      String
  code      String
  expiresAt DateTime
  createdAt DateTime @default(now())

  @@index([login])
  @@index([code])
  @@index([login, code])
}

model Favourite {
  id        String   @id @default(uuid())
  userId    String
  productId String?
  adId      String?
  createdAt DateTime @default(now())

  user    User     @relation(fields: [userId], references: [id], onDelete: Cascade)
  product Product? @relation(fields: [productId], references: [id], onDelete: Cascade)
  ad      Ad?      @relation(fields: [adId], references: [id], onDelete: Cascade)

  @@unique([userId, productId])
  @@unique([userId, adId])
}

model Balance {
  id       String   @id @default(uuid())
  userId   String   @unique
  value    Int
  currency Currency @default(RUB)

  user User @relation(fields: [userId], references: [id])
}

model Image {
  id        String  @id @default(uuid())
  url       String
  sortOrder Int
  alt       String?

  userAvatars  User[]           @relation("UserAvatar")
  categories   MarketCategory[]
  adCategories AdCategory[]
  products     ProductImage[]
  ads          AdImage[]
}

model MarketCategory {
  id        String @id @default(uuid())
  name      String
  slug      String
  sortOrder Int

  description String?
  parentId    String?
  imageId     String?

  isActive  Boolean   @default(true)
  deletedAt DateTime?

  parent   MarketCategory?  @relation("MarketCategoryTree", fields: [parentId], references: [id])
  children MarketCategory[] @relation("MarketCategoryTree")

  image    Image?    @relation(fields: [imageId], references: [id])
  products Product[]

  collectionCategories CatalogCollectionCategory[]

  @@map("Category")
}

model Product {
  id          String @id @default(uuid())
  categoryId  String
  title       String
  slug        String
  description String
  price       Int

  isActive  Boolean   @default(true)
  deletedAt DateTime?

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  category MarketCategory @relation(fields: [categoryId], references: [id])
  images   ProductImage[]

  cartItems  CartItem[]
  orderItems OrderItem[]
  favourites Favourite[]

  collectionProducts CatalogCollectionProduct[]
}

model AdCategory {
  id        String @id @default(uuid())
  name      String
  slug      String
  sortOrder Int

  description String?
  parentId    String?
  imageId     String?

