            {description}
          </p>
        </div>

        {action && (
          <div className="flex justify-center">
            {action.to ? (
              <Button asChild variant={action.variant}>
                <Link to={action.to}>{action.label}</Link>
              </Button>
            ) : (
              <Button
                type="button"
                variant={action.variant}
                onClick={action.onClick}
              >
                {action.label}
              </Button>
            )}
          </div>
        )}
      </div>
    </section>
  );
}
