import type { CSSProperties, UIEvent } from 'react';

import type { Ad } from '@/entities/ad';
import type { CatalogCategory } from '@/shared/types/catalog-category';
import type { Product } from '@/entities/product';
import { headerHeightVar } from '@/shared/header';
import { mobileNavigationHeightVar } from '@/shared/main-navigation';

import { GlobalSearchCategoryResults } from '../GlobalSearchCategoryResults';
import { GlobalSearchItemResults } from '../GlobalSearchItemResults';
import { GlobalSearchSectionResults } from '../GlobalSearchSectionResults';
import type { GlobalSearchSection } from '../../types/global-search';

type GlobalSearchDropdownProps = {
  isSearchReady: boolean;

  sections: GlobalSearchSection[];

  marketCategories: CatalogCategory[];
  adsCategories: CatalogCategory[];
  marketCategoryResults: CatalogCategory[];
  adsCategoryResults: CatalogCategory[];
  isMarketCategoriesPending?: boolean;
  isAdsCategoriesPending?: boolean;
  isMarketCategoriesError?: boolean;
  isAdsCategoriesError?: boolean;

  products: Product[];
  totalProducts: number;
  isProductsPending?: boolean;
  isProductsError?: boolean;
  hasMoreProducts?: boolean;

  ads: Ad[];
  totalAds: number;
  isAdsPending?: boolean;
  isAdsError?: boolean;
  hasMoreAds?: boolean;

  searchValue: string;

  onProductResultsScroll: (event: UIEvent<HTMLDivElement>) => void;
  onAdResultsScroll: (event: UIEvent<HTMLDivElement>) => void;
  onNavigate: () => void;
};

export function GlobalSearchDropdown({
  isSearchReady,

  sections,

  marketCategories,
  adsCategories,
  marketCategoryResults,
  adsCategoryResults,
  isMarketCategoriesPending = false,
  isAdsCategoriesPending = false,
  isMarketCategoriesError = false,
  isAdsCategoriesError = false,

  products,
  totalProducts,
  isProductsPending = false,
  isProductsError = false,
  hasMoreProducts = false,

  ads,
  totalAds,
  isAdsPending = false,
  isAdsError = false,
  hasMoreAds = false,

  searchValue,

  onProductResultsScroll,
  onAdResultsScroll,
  onNavigate,
}: GlobalSearchDropdownProps) {
  const globalSearchDescription = 'Найдите нужное в DNA.';
  const dropdownStyle = {
    '--global-search-mobile-height': `calc(100dvh - ${headerHeightVar()} - ${mobileNavigationHeightVar()} - 0.5rem)`,
  } as CSSProperties;

  return (
    <div className="absolute top-full right-0 left-0 z-[70] min-w-[320px] pt-2">
      <div
        className="max-h-[var(--global-search-mobile-height)] overflow-y-auto rounded-2xl border border-border bg-popover text-popover-foreground shadow-xl md:max-h-[calc(100dvh-var(--header-height,112px)-0.5rem)]"
        style={dropdownStyle}
      >
        {!isSearchReady ? (
          <p className="rounded-xl bg-muted/40 px-4 py-4 text-sm text-muted-foreground leading-[1.5]">
            {globalSearchDescription}
          </p>
        ) : (
          <div className="flex flex-col divide-y divide-border">
            <GlobalSearchItemResults
              products={products}
              totalProducts={totalProducts}
              ads={ads}
              totalAds={totalAds}
              searchValue={searchValue}
              isPending={isProductsPending || isAdsPending}
              isError={isProductsError || isAdsError}
              hasMore={hasMoreProducts || hasMoreAds}
              onScroll={(event) => {
                onProductResultsScroll(event);
                onAdResultsScroll(event);
              }}
              onNavigate={onNavigate}
            />

            <GlobalSearchCategoryResults
              marketCategories={marketCategories}
              adsCategories={adsCategories}
              marketCategoryResults={marketCategoryResults}
              adsCategoryResults={adsCategoryResults}
              searchValue={searchValue}
              isPending={isMarketCategoriesPending || isAdsCategoriesPending}
              isError={isMarketCategoriesError || isAdsCategoriesError}
              onNavigate={onNavigate}
            />

            <GlobalSearchSectionResults
              sections={sections}
              onNavigate={onNavigate}
            />
          </div>
        )}
      </div>
    </div>
  );
}
import { Link } from 'react-router-dom';

import type { CatalogCategory } from '@/shared/types/catalog-category';
import { getCategoryHref } from '@/shared/catalog';
import { PLATFORM_SECTION, type PlatformSectionId } from '@/shared/platform';
import { MarkHighlight } from '@/widgets/MarkHighlight';

type GlobalSearchCategoryResultsProps = {
  marketCategories: CatalogCategory[];
  adsCategories: CatalogCategory[];
  marketCategoryResults: CatalogCategory[];
  adsCategoryResults: CatalogCategory[];
  searchValue: string;
  isPending?: boolean;
  isError?: boolean;
  onNavigate: () => void;
};

export function GlobalSearchCategoryResults({
  marketCategories,
  adsCategories,
  marketCategoryResults,
  adsCategoryResults,
  searchValue,
  isPending = false,
  isError = false,
  onNavigate,
}: GlobalSearchCategoryResultsProps) {
  const categoryResults: Array<{
    category: CatalogCategory;
    allCategories: CatalogCategory[];
    section: PlatformSectionId;
  }> = [
    ...marketCategoryResults.map((category) => ({
      category,
      allCategories: marketCategories,
      section: PLATFORM_SECTION.MARKET,
    })),
    ...adsCategoryResults.map((category) => ({
      category,
      allCategories: adsCategories,
      section: PLATFORM_SECTION.ADS,
    })),
  ];

  return (
    <section className="flex flex-col gap-3 p-4">
      <div className="flex items-center justify-between gap-3">
        <h3 className="text-sm font-semibold">Категории</h3>

        <span className="text-xs text-muted-foreground">
          {categoryResults.length}
        </span>
      </div>

      <div className="grid gap-1">
        {isPending && (
          <p className="rounded-lg bg-muted/40 p-3 text-sm text-muted-foreground">
            Ищем категории...
          </p>
        )}

        {isError && (
          <p className="rounded-lg bg-destructive/10 p-3 text-sm text-destructive">
            Не удалось загрузить категории.
          </p>
        )}

        {!isPending && !isError && categoryResults.length === 0 && (
          <p className="rounded-lg bg-muted/40 p-3 text-sm text-muted-foreground">
            Категории не найдены.
          </p>
        )}

        {!isPending &&
          !isError &&
          categoryResults.map(({ category, allCategories, section }) => (
            <Link
              key={`${section}-${category.id}`}
              to={getCategoryHref(allCategories, category.id, section)}
              onClick={onNavigate}
              className="grid grid-cols-[56px_minmax(0,1fr)] gap-3 rounded-xl p-2 transition-colors hover:bg-muted"
            >
              <div className="size-14 overflow-hidden rounded-md bg-muted">
                {category.image ? (
                  <img
                    src={category.image.url}
                    alt={category.image.alt ?? category.name}
                    className="h-full w-full object-cover"
                  />
                ) : (
                  <div className="flex h-full w-full items-center justify-center text-xs font-semibold text-muted-foreground">
                    {category.name.slice(0, 1)}
                  </div>
                )}
              </div>

              <div className="min-w-0 py-1">
                <div className="flex items-start justify-between gap-2">
                  <p className="line-clamp-1 text-sm font-medium">
                    <MarkHighlight text={category.name} searchValue={searchValue} level={1} />
                  </p>
                  <span className="shrink-0 rounded-md bg-muted px-1.5 py-1 text-[10px] font-medium leading-none text-muted-foreground">
                    {section === PLATFORM_SECTION.MARKET ? 'Маркет' : 'Доска'}
                  </span>
                </div>

                <p className="mt-0.5 line-clamp-1 text-xs text-muted-foreground">
                  {category.description ? (
                    <MarkHighlight text={category.description} searchValue={searchValue} level={2} />
                  ) : (
                    <MarkHighlight text={category.path} searchValue={searchValue} level={2} />
                  )}
                </p>
              </div>
            </Link>
          ))}
      </div>
    </section>
  );
}
import { Link } from 'react-router-dom';

import type { GlobalSearchSection } from '../../types/global-search';

type GlobalSearchSectionResultsProps = {
  sections: GlobalSearchSection[];
  onNavigate: () => void;
};

export function GlobalSearchSectionResults({
  sections,
  onNavigate,
}: GlobalSearchSectionResultsProps) {
  return (
    <section className="flex flex-col gap-3 p-4">
      <div className="flex items-center justify-between gap-3">
        <h3 className="text-sm font-semibold">Разделы</h3>

        <span className="text-xs text-muted-foreground">
          {sections.length}
        </span>
      </div>

      <div className="grid gap-1">
        {sections.length > 0 ? (
          sections.map((section) => (
            <Link
              key={section.id}
              to={section.href}
              onClick={onNavigate}
              className="rounded-lg px-3 py-2 transition-colors hover:bg-muted"
            >
              <p className="text-sm font-medium">{section.title}</p>

              <p className="mt-0.5 line-clamp-2 text-xs leading-5 text-muted-foreground">
                {section.description}
              </p>
            </Link>
          ))
        ) : (
          <p className="rounded-lg bg-muted/40 px-3 py-3 text-sm text-muted-foreground">
            Разделы не найдены.
          </p>
        )}
      </div>
    </section>
  );
}
import { SearchInput } from '@/components/ui/SearchInput';
import { cn } from '@/shared/utils/cn';

import { GlobalSearchDropdown } from './components/GlobalSearchDropdown';
import { useGlobalSearch } from './hooks/use-global-search';

type GlobalSearchProps = {
  placeholder?: string;
  className?: string;
  inputClassName?: string;
  onOpen?: () => void;
};

export function GlobalSearch({
  placeholder = 'Поиск по DNA',
  className,
  inputClassName,
  onOpen,
}: GlobalSearchProps) {
  const {
    containerRef,
    searchValue,
    isOpen,
    isSearchReady,

    sectionResults,

    marketCategories,
    adsCategories,
    marketCategoryResults,
    adsCategoryResults,
    isMarketCategoriesPending,
    isAdsCategoriesPending,
    isMarketCategoriesError,
    isAdsCategoriesError,

    productResults,
    visibleProducts,
    hasMoreProducts,
    isProductsPending,
    isProductsError,

    adResults,
    visibleAds,
    hasMoreAds,
    isAdsPending,
    isAdsError,

    setSearchValue,
    openSearch,
    handleResultClick,
    handleProductResultsScroll,
    handleAdResultsScroll,
  } = useGlobalSearch();

  function handleFocus() {
    openSearch();
    onOpen?.();
  }

  return (
    <div ref={containerRef} className={cn('relative w-full', className)}>
      <SearchInput
        value={searchValue}
        placeholder={placeholder}
        autoComplete="off"
        className={inputClassName}
        onFocus={handleFocus}
        onChange={(event) => setSearchValue(event.target.value)}
      />

      {isOpen && (
        <GlobalSearchDropdown
          isSearchReady={isSearchReady}
          sections={sectionResults}
          marketCategories={marketCategories}
          adsCategories={adsCategories}
          marketCategoryResults={marketCategoryResults}
          adsCategoryResults={adsCategoryResults}
          isMarketCategoriesPending={isMarketCategoriesPending}
          isAdsCategoriesPending={isAdsCategoriesPending}
          isMarketCategoriesError={isMarketCategoriesError}
          isAdsCategoriesError={isAdsCategoriesError}
          products={visibleProducts}
          totalProducts={productResults.length}
          isProductsPending={isProductsPending}
          isProductsError={isProductsError}
          hasMoreProducts={hasMoreProducts}
          ads={visibleAds}
          totalAds={adResults.length}
          isAdsPending={isAdsPending}
          isAdsError={isAdsError}
          hasMoreAds={hasMoreAds}
          searchValue={searchValue}
          onProductResultsScroll={handleProductResultsScroll}
          onAdResultsScroll={handleAdResultsScroll}
          onNavigate={handleResultClick}
        />
      )}
    </div>
  );
}
